-- ============================================================
-- SEED EXT 6: Módulo 18 — Nominalization (ex 202-300)
-- Blocos 71-82 | 99 exercícios
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'nominalization';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo nominalization não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: Sufixos -tion/-sion/-ation (8 ex)
  (cid,71,202,'gap_fill','The _____ (analyze → noun) of the data revealed inconsistencies that had not been apparent in preliminary _____ (examine → noun) of the results.','analysis / examination',NULL,'''analyze → analysis'' irregular; ''examine → examination'' (-ation). Both core nominalization suffixes.','easy'),
  (cid,71,203,'gap_fill','The _____ (implement → noun) of the new framework requires careful _____ (coordinate → noun) among the departments responsible for its _____ (execute → noun).','implementation / coordination / execution',NULL,'-ment, -ation, -tion. Core nominalization vocabulary.','easy'),
  (cid,71,204,'gap_fill','The _____ (adopt → noun) of a more rigorous _____ (evaluate → noun) framework would enable greater _____ (precise → noun) in the _____ (assess → noun) of outcomes.','adoption / evaluation / precision / assessment',NULL,'-tion, -ation, -ion (precision from precise), -ment.','medium'),
  (cid,71,205,'gap_fill','The _____ (regulate → noun) of financial markets requires the _____ (apply → noun) of complex _____ (judge → noun) about when to intervene and what _____ (intervene → noun) is appropriate.','regulation / application / judgments / intervention',NULL,'-ation, -ation, -ment (judgments), -tion.','medium'),
  (cid,71,206,'gap_fill','The _____ (collaborate → noun) between the two institutions led to the _____ (produce → noun) of influential publications and the _____ (establish → noun) of a joint research center.','collaboration / production / establishment',NULL,'-ation, -tion, -ment.','easy'),
  (cid,71,207,'gap_fill','The _____ (investigate → noun) concluded that the _____ (fail → noun) of the oversight mechanism was attributable to _____ (neglect → noun) of established protocols.','investigation / failure / neglect',NULL,'-ation, -ure, neglect = noun/verb identical.','medium'),
  (cid,71,208,'gap_fill','The _____ (recognize → noun) that institutional _____ (perform → noun) is multidimensional led to _____ (develop → noun) of more sophisticated _____ (measure → noun) frameworks.','recognition / performance / development / measurement',NULL,'-ition, -ance, -ment, -ment.','medium'),
  (cid,71,209,'multiple_choice','Which nominalized form CORRECTLY completes this sentence? ''The _____ of new policies requires consultation.''','implementation','["implementing","implemented","implementer","implementation"]','''Implementation'' = verb ''implement'' + -ation suffix. Formal subject noun.','easy'),

  -- BLOCK 72: Sufixos -ment, -ance/-ence, -ity (8 ex)
  (cid,72,210,'gap_fill','The _____ (govern → noun) of international institutions depends on the _____ (willing → noun) of member states to subordinate short-term _____ (convenient → noun) to long-term _____ (stable → noun).','governance / willingness / convenience / stability',NULL,'-ance (governance), -ness (willingness), -ience (convenience), -ity (stability).','hard'),
  (cid,72,211,'gap_fill','The _____ (accountable → noun) of public institutions requires both _____ (transparent → noun) in operations and _____ (accessible → noun) of information to those with legitimate interest.','accountability / transparency / accessibility',NULL,'-ility, -ency, -ility. All from adjectives.','hard'),
  (cid,72,212,'gap_fill','The _____ (effective → noun) of a policy depends on both its _____ (appropriate → noun) to the problem and the _____ (efficient → noun) with which it is implemented.','effectiveness / appropriateness / efficiency',NULL,'-ness, -ness, -cy. Adjective-to-noun derivation.','medium'),
  (cid,72,213,'gap_fill','The _____ (signify → noun) of the finding lies not in its _____ (novel → noun) but in its _____ (confirm → noun) of a _____ (relate → noun) long suspected.','significance / novelty / confirmation / relationship',NULL,'Significance (-ance), novelty (-ty), confirmation (-ation), relationship (-ship).','hard'),
  (cid,72,214,'gap_fill','The _____ (persist → noun) of _____ (inequity → noun) in access to education reflects deeper _____ (structural → noun) barriers that resist short-term _____ (intervene → noun).','persistence / inequity / structural / interventions',NULL,'Persistence (-ence); structural = adjective; interventions (-tion).','hard'),
  (cid,72,215,'gap_fill','The _____ (stable → noun) of the financial system depends on the _____ (capable → noun) of regulators to maintain liquidity and the _____ (trust → noun) of market participants in institutional resilience.','stability / capability / trust',NULL,'Stability (-ity), capability (-ility), trust = noun unchanged.','medium'),
  (cid,72,216,'gap_fill','The _____ (capable → noun) to learn from _____ (fail → noun) is a defining _____ (character → noun) of resilient institutions that _____ (incorporate → noun) information from disappointing experience into future planning.','capability / failures / characteristic / incorporate',NULL,'Capability (-ility), failures (-ure plural), characteristic (noun), incorporate (verb here).','hard'),
  (cid,72,217,'multiple_choice','Which sentence uses nominalization MOST effectively for academic writing?','The implementation of the framework required extensive consultation with stakeholders.','["Implementing the framework required consulting with stakeholders.","The implementation of the framework required extensive consultation with stakeholders.","They implemented the framework and consulted stakeholders.","The framework was implemented after extensive consultation had taken place."]','Option B: two nominalizations (''implementation,'' ''consultation'') create formal density.','medium'),

  -- BLOCK 73: Sufixos -ity, -ness, -al, -ure (8 ex)
  (cid,73,218,'gap_fill','The _____ (choose → noun) of an appropriate _____ (intervene → noun) requires growing _____ (understand → noun) of the _____ (complex → noun) of the situation.','choice / intervention / understanding / complexity',NULL,'''Choice'' is irregular (choose → choice); -tion, gerund-noun, -ity.','hard'),
  (cid,73,219,'gap_fill','The _____ (fail → noun) to develop _____ (clear → noun) _____ (define → noun) of key concepts is a recurring problem that hinders _____ (compare → noun) and _____ (accumulate → noun) of knowledge.','failure / clear / definition / comparison / accumulation',NULL,'Failure (-ure), definition (-tion from define), comparison (-ison), accumulation (-tion).','hard'),
  (cid,73,220,'gap_fill','The _____ (grow → noun) of concern about the long-term _____ (sustain → noun) of current practices has accelerated the _____ (search → noun) for alternative approaches.','growth / sustainability / search',NULL,'''Growth'' irregular (grow → growth); sustainability (-ility); search = noun unchanged.','medium'),
  (cid,73,221,'gap_fill','The _____ (know → noun) that organizational _____ (behave → noun) is shaped by _____ (incentive → noun) rather than _____ (intent → noun) has important _____ (imply → noun) for reform design.','knowledge / behavior / incentives / intent / implications',NULL,'''Knowledge'' irregular; behavior (-ior); implications (-tion from imply).','hard'),
  (cid,73,222,'gap_fill','The _____ (perceive → noun) that regulatory _____ (intervene → noun) reduces _____ (efficient → noun) is a persistent _____ (misunderstand → noun) that careful _____ (analyze → noun) of evidence fails to support.','perception / intervention / efficiency / misunderstanding / analysis',NULL,'Perception (irregular -tion); misunderstanding (compound); analysis irregular.','hard'),
  (cid,73,223,'gap_fill','The _____ (believe → noun) that formal _____ (train → noun) is necessary but not sufficient for effective _____ (lead → noun) is widely shared among practitioners.','belief / training / leadership',NULL,'''Belief'' irregular (believe → belief); training (gerund-noun); leadership (-ship).','medium'),
  (cid,73,224,'gap_fill','The _____ (think → noun) underpinning the reform is that _____ (strong → noun) in _____ (govern → noun) requires _____ (commit → noun) to both _____ (accountable → noun) and _____ (perform → noun).','thinking / strength / governance / commitment / accountability / performance',NULL,'Thinking (gerund as noun), strength (irregular), governance (-ance), commitment (-ment), accountability (-ity), performance (-ance).','hard'),
  (cid,73,225,'multiple_choice','Which nominalized form is MOST appropriate? ''The _____ of formal rules into organizational practice remains the central challenge.''','translation','["translating","translated","translator","translation"]','''Translation of X into Y'' = standard academic nominalization.','easy'),

  -- BLOCK 74: Derivação irregular + compostos (8 ex)
  (cid,74,226,'gap_fill','The _____ (justify → noun) for regulatory _____ (intervene → noun) rests on the _____ (exist → noun) of market _____ (fail → noun) that, without corrective action, produce suboptimal _____ (outcome → noun).','justification / intervention / existence / failures / outcomes',NULL,'Justification (-tion), existence (-ence), failures (-ure plural).','hard'),
  (cid,74,227,'gap_fill','The _____ (distribute → noun) of benefits and costs across different stakeholder groups is a central _____ (consider → noun) in any _____ (assess → noun) of policy _____ (effective → noun).','distribution / consideration / assessment / effectiveness',NULL,'Distribution (-tion), consideration (-tion), assessment (-ment), effectiveness (-ness).','hard'),
  (cid,74,228,'gap_fill','The _____ (measure → noun) of governance _____ (quality → noun) requires _____ (operationalize → noun) a concept that is inherently multidimensional and resists _____ (reduce → noun) to any single _____ (indicate → noun).','measurement / quality / operationalizing / reduction / indicator',NULL,'Measurement (-ment), operationalizing (gerund), reduction (-tion), indicator (-or).','hard'),
  (cid,74,229,'gap_fill','The _____ (identify → noun) of lessons from _____ (compare → noun) analysis requires _____ (attend → noun) to context — the _____ (recognize → noun) that institutions embedded in different environments may behave differently even when formally similar.','identification / comparative / attention / recognition',NULL,'Identification (-tion), comparative (adjective from compare), attention (-tion), recognition (-tion).','hard'),
  (cid,74,230,'gap_fill','The _____ (contribute → noun) of qualitative methods to the _____ (understand → noun) of governance processes lies in their _____ (capable → noun) to illuminate mechanisms that quantitative approaches cannot capture.','contribution / understanding / capability',NULL,'Contribution (-tion), understanding (gerund-noun), capability (-ility).','medium'),
  (cid,74,231,'gap_fill','The _____ (sustain → noun) of reform gains depends on _____ (build → noun) institutionalized _____ (capable → noun) for ongoing _____ (adapt → noun) rather than the _____ (create → noun) of static systems that resist _____ (modify → noun).','sustainability / building / capability / adaptation / creation / modification',NULL,'Sustainability (-ity), building (gerund), adaptation (-tion), creation (-tion), modification (-tion).','hard'),
  (cid,74,232,'gap_fill','The _____ (complex → noun) of the challenges faced by contemporary governance systems demands intellectual _____ (humble → noun) about the _____ (limit → noun) of any single discipline.','complexity / humility / limits',NULL,'Complexity (-ity), humility (-ity from humble), limits (plain noun).','medium'),
  (cid,74,233,'multiple_choice','Which sentence uses nominalization MOST effectively to convey academic tone?','The consolidation of democratic institutions requires sustained investment in civic education.','["Consolidating democratic institutions requires investing in civic education over time.","Democratic institutions consolidate when civic education is invested in.","The consolidation of democratic institutions requires sustained investment in civic education.","They consolidated democratic institutions by investing in civic education."]','Option C: ''consolidation'' + ''investment'' = double nominalization, formal.','medium'),

  -- BLOCK 75: Nominalization em contexto acadêmico (8 ex)
  (cid,75,234,'gap_fill','The _____ (assert → noun) that economic _____ (develop → noun) is a sufficient _____ (condition → noun) for democratic _____ (consolidate → noun) represents a significant _____ (oversimplify → noun) of a complex _____ (relate → noun).','assertion / development / condition / consolidation / oversimplification / relationship',NULL,'Assertion (-tion), development (-ment), consolidation (-tion), oversimplification (-tion compound), relationship (-ship).','hard'),
  (cid,75,235,'gap_fill','The _____ (emerge → noun) of digital platforms as dominant intermediaries has necessitated fundamental _____ (reconsider → noun) of existing regulatory _____ (framework → noun).','emergence / reconsideration / frameworks',NULL,'Emergence (-ence), reconsideration (re- + -ation), frameworks (plain noun).','medium'),
  (cid,75,236,'gap_fill','A comprehensive _____ (assess → noun) of program _____ (effective → noun) requires _____ (attend → noun) to both intended _____ (outcome → noun) and the unintended _____ (consequence → noun) that may accompany well-designed _____ (intervene → noun).','assessment / effectiveness / attention / outcomes / consequences / interventions',NULL,'Assessment (-ment), effectiveness (-ness), attention (-tion), interventions (-tion).','hard'),
  (cid,75,237,'gap_fill','The _____ (recognize → noun) of systemic _____ (complex → noun) as a defining characteristic of governance challenges has opened new avenues for _____ (research → noun).','recognition / complexity / research',NULL,'Recognition (-tion), complexity (-ity), research = noun unchanged.','medium'),
  (cid,75,238,'gap_fill','The _____ (persist → noun) of these challenges despite significant _____ (invest → noun) reflects the _____ (complex → noun) of the underlying _____ (issue → noun).','persistence / investment / complexity / issues',NULL,'Persistence (-ence), investment (-ment), complexity (-ity).','medium'),
  (cid,75,239,'gap_fill','The _____ (argument → noun) that economic _____ (develop → noun) is a necessary precondition for democratic _____ (consolidate → noun) has been challenged by the _____ (emergence → noun) of cases in which _____ (democratize → noun) preceded economic _____ (transform → noun).','argument / development / consolidation / emergence / democratization / transformation',NULL,'Development (-ment), consolidation (-tion), democratization (-tion), transformation (-tion).','hard'),
  (cid,75,240,'gap_fill','The _____ (assume → noun) that formal rules are self-enforcing overlooks the _____ (important → noun) of informal norms and social _____ (pressure → noun) in shaping organizational _____ (behave → noun).','assumption / importance / pressure / behavior',NULL,'Assumption (-tion), importance (-ance), behavior (-ior from behave).','hard'),
  (cid,75,241,'multiple_choice','Which nominalized version MOST improves the formality of ''When they manage poorly, public institutions lose citizens'' trust''?','Poor management of public institutions leads to erosion of public trust.','["Poor managing leads to trust erosion in public institutions.","Public institutions lose trust when they are poorly managed.","Poor management of public institutions leads to erosion of public trust.","The management of public institutions, when poor, leads to loss of trust."]','Option C: ''management'' + ''erosion'' = double nominalization, concise and formal.','medium'),

  -- BLOCK 76: TOEFL Reading — Nominalization (8 ex)
  (cid,76,242,'multiple_choice','[TOEFL Reading] ''The establishment of clear accountability mechanisms is a precondition for effective governance.'' The nominalization ''establishment'' derives from:','establish (verb)','["establish (verb)","established (adjective)","establisher (noun)","establishable (adjective)"]','''Establishment'' = ''establish'' + -ment suffix.','easy'),
  (cid,76,243,'gap_fill','[TOEFL Reading] ''The _____ (analyze → noun) _____ (reveal) that _____ (implement → noun) of the policy _____ (require) significant _____ (adjust → noun) to existing procedures.'' Best forms?','analysis / revealed / implementation / required / adjustment',NULL,'Analysis (irregular), implementation (-tion), adjustment (-ment).','medium'),
  (cid,76,244,'multiple_choice','[TOEFL Reading] ''The recognition of complexity allows for more nuanced evaluation.'' Which words are nominalizations?','recognition and evaluation','["complexity and nuanced","recognition and evaluation","the and for","more and nuanced"]','''Recognition'' (from recognize) and ''evaluation'' (from evaluate). Note: ''complexity'' is also a nominalization.','easy'),
  (cid,76,245,'gap_fill','[TOEFL Reading] ''The _____ (persist → noun) of these _____ (challenge → noun) despite significant _____ (invest → noun) reflects the _____ (complex → noun) of the underlying issues.'' Best forms?','persistence / challenges / investment / complexity',NULL,'Persistence (-ence), investment (-ment), complexity (-ity).','medium'),
  (cid,76,246,'gap_fill','[TOEFL Reading] ''The _____ (observe → noun) that institutions evolve in _____ (respond → noun) to environmental change challenges earlier _____ (characterize → noun) of them as static structures.'' Best forms?','observation / response / characterizations',NULL,'Observation (-tion), response (-se from respond), characterizations (-tion plural).','medium'),
  (cid,76,247,'gap_fill','[TOEFL Reading] ''The _____ (fail → noun) of previous reform _____ (attempt → noun) was due to _____ (insufficient → noun) in design rather than _____ (implement → noun).'' Best forms?','failure / attempts / insufficiency / implementation',NULL,'Failure (-ure), insufficiency (-cy from insufficient), implementation (-tion).','medium'),
  (cid,76,248,'gap_fill','[TOEFL Reading] ''The _____ (develop → noun) of effective _____ (govern → noun) structures requires _____ (attend → noun) to _____ (incentive → noun) alignment as well as formal mandates.'' Best forms?','development / governance / attention / incentive',NULL,'Development (-ment), governance (-ance), attention (-tion), incentive (noun unchanged).','medium'),
  (cid,76,249,'multiple_choice','[TOEFL Reading] Which sentence uses nominalization MOST effectively to convey academic tone?','The persistence of governance failures despite substantial investment in reform suggests that the determinants of institutional performance are more complex than simple design models imply.','["Governance keeps failing despite investing substantially, suggesting institutions are complex.","The persistence of governance failures despite substantial investment in reform suggests that the determinants of institutional performance are more complex than simple design models imply.","Although governments invest in reform, governance fails, which is complex.","The failures of governance persisting despite investment suggests complexity."]','Option B: persistence, failures, investment, determinants, performance — dense academic nominalization.','hard'),

  -- BLOCK 77: TOEFL Speaking (8 ex)
  (cid,77,250,'production','[TOEFL Speaking — 45s] Summarize a reading on institutional reform using nominalization throughout.','',NULL,'The reading examines the conditions under which institutional reform leads to sustained improvement in governance performance. It argues that the success of reform depends on three factors: the quality of initial design, the adequacy of implementation mechanisms, and the existence of accountability structures capable of detecting underperformance. The reading notes that the failure of many reform efforts is attributable not to deficiencies in policy design but to the absence of effective implementation oversight. The analysis concludes that the achievement of lasting improvement requires sustained investment in institutional capacity, not merely the adoption of formal rules, and that the measurement of outcomes is essential to the adaptation of strategy.','hard'),
  (cid,77,251,'production','[TOEFL Speaking — 45s] The professor critiques the reading. Use nominalization throughout.','',NULL,'The professor challenges the reading''s characterization of reform failure as a consequence of poor design or insufficient oversight. She argues that this misses the more fundamental issue: the misalignment of incentives. Her central observation is that the persistence of underperformance is often a product not of incompetence but of deliberate resistance by stakeholders whose interests are served by maintenance of the status quo. The professor concludes that any analysis that does not attend to the political economy of change — the distribution of costs and benefits and the organization of opposition — is likely to produce recommendations whose adoption is impractical regardless of their analytical merit.','hard'),
  (cid,77,252,'production','[TOEFL Speaking — 60s] Compare the reading and professor on governance reform using nominalization.','',NULL,'The reading and the professor offer contrasting analyses of the determinants of governance reform success. The reading places emphasis on technical dimensions — the quality of design, adequacy of implementation mechanisms, and availability of accountability structures — treating improvement as a function of getting these elements right. Its characterization of failure as a consequence of technical deficiency leads to recommendations focused on capacity building and institutional strengthening. The professor, by contrast, argues that the fundamental obstacle is not insufficiency of technical capacity but misalignment of incentives. Her observation that institutions underperform not because their actors lack knowledge but because they lack motivation reframes the problem from capacity to political economy. The implication is that creation of conditions for successful reform requires not better design but more effective management of the political environment. The reconciliation of these perspectives suggests that successful reform requires simultaneous attention to both technical and political dimensions, and that neglect of either is sufficient to undermine prospects for success.','hard'),
  (cid,77,253,'gap_fill','[TOEFL Speaking] The _____ (consolidate → noun) of democracy requires _____ (attend → noun) to _____ (incentive → noun) alignment, institutional _____ (develop → noun), and civic _____ (participate → noun) — not merely the _____ (adopt → noun) of formal electoral procedures.','consolidation / attention / incentive / development / participation / adoption',NULL,'Consolidation (-tion), attention (-tion), development (-ment), participation (-tion), adoption (-tion).','hard'),
  (cid,77,254,'gap_fill','[TOEFL Speaking] The _____ (persist → noun) of challenges despite significant _____ (invest → noun) suggests that the root causes lie in structural features that resist short-term _____ (intervene → noun).','persistence / investment / interventions',NULL,'Persistence (-ence), investment (-ment), interventions (-tion).','medium'),
  (cid,77,255,'gap_fill','[TOEFL Speaking] The _____ (evaluate → noun) of anti-corruption _____ (intervene → noun) requires _____ (attend → noun) to the distinction between _____ (reduce → noun) in perceived corruption and _____ (reduce → noun) in actual corrupt behavior.','evaluation / interventions / attention / reduction / reduction',NULL,'Evaluation (-tion), interventions (-tion), attention (-tion), reduction (-tion).','hard'),
  (cid,77,256,'gap_fill','[TOEFL Speaking] The _____ (adopt → noun) of evidence-based approaches to _____ (policy-make → noun) requires _____ (invest → noun) in research capacity and the _____ (develop → noun) of mechanisms for _____ (translate → noun) findings into practice.','adoption / policy-making / investment / development / translating',NULL,'Adoption (-tion), investment (-ment), development (-ment), translating (gerund).','hard'),
  (cid,77,257,'multiple_choice','[TOEFL Speaking] Which nominalized response BEST demonstrates academic fluency for a 45-second task?','The reading''s central argument concerns the relationship between institutional design and governance performance, highlighting three dimensions of reform success.','["The reading talks about how institutions work and why reforms succeed or fail.","The reading''s central argument concerns the relationship between institutional design and governance performance, highlighting three dimensions of reform success.","The reading is saying that institutions need good designs for reforms to work well.","In the reading, they argue about institutional design and its relationship to performance."]','Option B: ''argument,'' ''relationship,'' ''design,'' ''performance,'' ''dimensions'' = high nominalization density appropriate for academic speaking.','medium'),

  -- BLOCK 78: TOEFL Writing — produção (8 ex)
  (cid,78,258,'production','[TOEFL Writing — 200 words] Write a body paragraph on institutional capacity using nominalization as the primary style device.','',NULL,'The development of institutional capacity is widely recognized as a prerequisite for effective governance, yet the operationalization of this concept in practice has proved considerably more difficult than its articulation in policy documents. The measurement of capacity is complicated by its multidimensionality: it encompasses the availability of skilled personnel, the adequacy of organizational structures, the appropriateness of incentive systems, and the existence of mechanisms for the accumulation and application of organizational learning. The assumption that the provision of technical assistance and training is sufficient for capacity development has been challenged by evidence demonstrating that the sustainability of gains depends on alignment between formal organizational structure and informal norms. The implication for policy is that investment in capacity development must be accompanied by attention to organizational culture — a factor considerably more difficult to change than formal structures but considerably more important for the determination of organizational performance. The recognition of this complexity is not a counsel of despair but a call for more sophisticated understanding of what effective capacity development requires and what realistic expectation of its pace and trajectory is appropriate.','hard'),
  (cid,78,259,'production','[TOEFL Writing — 200 words] Write a body paragraph on transparency and accountability using nominalization.','',NULL,'The relationship between transparency and accountability is central to the theory and practice of good governance, yet the assumption that the promotion of transparency is sufficient for the achievement of accountability has been challenged by accumulating evidence. The publication of information about government performance, while a necessary precondition for accountability, does not automatically lead to the mobilization of political pressure for improvement. The translation of transparency into accountability requires the existence of capable oversight actors with the capacity to process complex information and the organizational resources to sustain the engagement that effective accountability demands. The recognition that the effectiveness of transparency depends on the broader institutional environment has significant implications for the design of accountability frameworks: the adoption of transparency requirements in contexts lacking complementary institutions may produce the appearance of accountability without its substance. The achievement of genuine accountability requires, therefore, not merely the creation of transparency mechanisms but the development of the entire ecosystem of institutions, actors, and practices that give transparency its practical significance.','hard'),
  (cid,78,260,'gap_fill','[TOEFL Writing] The _____ (recognize → noun) that governance _____ (fail → noun) is rarely mono-causal has led to the _____ (develop → noun) of more integrated analytical frameworks that _____ (attend → noun) to multiple _____ (dimension → noun) simultaneously.','recognition / failure / development / attend / dimensions',NULL,'Recognition (-tion), failure (-ure), development (-ment), dimensions (plain noun).','hard'),
  (cid,78,261,'gap_fill','[TOEFL Writing] The _____ (create → noun) of effective _____ (incentive → noun) structures requires deep _____ (understand → noun) of the _____ (motivate → noun) of all relevant actors.','creation / incentive / understanding / motivations',NULL,'Creation (-tion), understanding (gerund-noun), motivations (-tion).','medium'),
  (cid,78,262,'gap_fill','[TOEFL Writing] The _____ (assume → noun) that formal rules are self-enforcing overlooks the _____ (importance → noun) of informal norms and social pressure in shaping organizational _____ (behave → noun).','assumption / importance / behavior',NULL,'Assumption (-tion), importance (-ance), behavior (-ior from behave).','medium'),
  (cid,78,263,'gap_fill','[TOEFL Writing] The _____ (recognition → noun) of _____ (uncertain → noun) as an inherent feature of complex systems has important _____ (implication → noun) for _____ (expectation → noun) about the _____ (precision → noun) of analysis and the _____ (confident → noun) of predictions.','recognition / uncertainty / implications / expectations / precision / confidence',NULL,'Uncertainty (-ty), implications (-tion), expectations (-tion), precision (-ion), confidence (-ence).','hard'),
  (cid,78,264,'gap_fill','[TOEFL Writing] The _____ (transform → noun) of governance _____ (arrangement → noun) requires not merely the _____ (replace → noun) of existing structures but the _____ (cultivate → noun) of new norms, practices, and _____ (expectation → noun) among those responsible for operating them.','transformation / arrangements / replacement / cultivation / expectations',NULL,'Transformation (-tion), replacement (-ment), cultivation (-tion), expectations (-tion).','hard'),
  (cid,78,265,'production','[TOEFL Writing — 200 words] Write a paragraph integrating the reading and lecture on why reform is difficult.','',NULL,'The reading and the lecture converge on the conclusion that the difficulty of governance reform is a product of multiple reinforcing factors, but they diverge significantly in their characterization of which factors are most fundamental. The reading''s emphasis on the technical dimensions of reform — the quality of design, the adequacy of implementation capacity, and the availability of performance measurement systems — produces an analysis that is thorough in its treatment of the mechanics of reform but insufficiently attentive to the political economy in which those mechanics must operate. The lecture''s observation that the persistence of poor performance is often a product of deliberate resistance rather than ignorance or incapacity reframes the problem in ways that have significant implications for reform strategy. If the failure of reform is attributable to the active opposition of well-organized interests, then the prescription of capacity development misidentifies the obstacle and misses the opportunity for effective intervention. The reconciliation of these perspectives suggests that the most realistic approach combines technical strengthening with political management — the simultaneous attention to what needs to change and to the organization of support that successful transformation requires.','hard'),

  -- BLOCK 79: Análise crítica avançada (8 ex)
  (cid,79,266,'gap_fill','The _____ (justify → noun) for regulatory intervention rests on the _____ (exist → noun) of market _____ (fail → noun) that, absent corrective action, produce _____ (outcome → noun) suboptimal from the _____ (perspective → noun) of social welfare.','justification / existence / failures / outcomes / perspective',NULL,'Justification (-tion), existence (-ence), failures (-ure plural), perspective (plain noun).','hard'),
  (cid,79,267,'gap_fill','The _____ (significant → noun) of informal norms in shaping organizational _____ (behave → noun) has been neglected in analyses that prioritize formal _____ (structure → noun) and _____ (procedure → noun).','significance / behavior / structures / procedures',NULL,'Significance (-ance from signify), behavior (-ior), structures (plain noun).','hard'),
  (cid,79,268,'gap_fill','The _____ (lack → noun) of clear _____ (define → noun) of key concepts is a recurring problem in governance _____ (research → noun), one that hinders _____ (compare → noun) and _____ (accumulate → noun) of knowledge.','lack / definition / research / comparison / accumulation',NULL,'Definition (-tion), comparison (-ison), accumulation (-tion).','hard'),
  (cid,79,269,'gap_fill','The _____ (invest → noun) in governance reform must be accompanied by realistic _____ (assess → noun) of what change is achievable within given political _____ (constraint → noun).','investment / assessment / constraints',NULL,'Investment (-ment), assessment (-ment), constraints (plain noun).','medium'),
  (cid,79,270,'gap_fill','The _____ (design → noun) of accountability mechanisms requires careful _____ (attend → noun) to incentives — _____ (recognize → noun) that formal rules alone cannot guarantee the _____ (behave → noun) they seek to elicit.','design / attention / recognition / behavior',NULL,'Design (noun unchanged), attention (-tion), recognition (-tion), behavior (-ior).','hard'),
  (cid,79,271,'gap_fill','The _____ (sustain → noun) of institutional quality over time requires both _____ (vigilance → noun) against erosion and _____ (willing → noun) to invest in _____ (renew → noun) even when immediate returns are uncertain.','sustainability / vigilance / willingness / renewal',NULL,'Sustainability (-ity), vigilance (plain noun), willingness (-ness), renewal (-al from renew).','medium'),
  (cid,79,272,'gap_fill','The _____ (distribution → noun) of benefits and costs across stakeholder groups is a central _____ (consider → noun) in any _____ (assess → noun) of policy _____ (effective → noun).','distribution / consideration / assessment / effectiveness',NULL,'Consideration (-tion), assessment (-ment), effectiveness (-ness).','hard'),
  (cid,79,273,'multiple_choice','Which nominalized form BEST completes: ''The _____ of evidence across thirty years of research supports the conclusion that institutional quality matters most.''?','accumulation','["accumulating","accumulated","accumulator","accumulation"]','''The accumulation of evidence'' = formal nominalized subject. ''Accumulating'' (gerund) also works but ''accumulation'' is more formal.','easy'),

  -- BLOCK 80: Síntese (9 ex)
  (cid,80,274,'production','[TOEFL Writing — 200 words] Write a body paragraph on the measurement of governance quality.','',NULL,'The measurement of governance quality is one of the most contested methodological challenges in contemporary political science, reflecting the inherent difficulty of operationalizing a concept that encompasses multiple dimensions simultaneously important and difficult to observe directly. The development of composite indices represents an attempt to aggregate information from diverse sources into a summary measure that permits cross-national comparison and longitudinal tracking of change. The criticism of these indices has centered on several concerns: the arbitrariness of the weighting schemes, the reliance on expert perceptions that may reflect reputation rather than actual performance, the compression of multidimensional phenomena into unidimensional rankings, and the potential for the availability of measurement to shape the definition of the concept. The recognition of these limitations does not invalidate the enterprise of governance measurement, but it does require that the use of available indices be accompanied by careful attention to what they do and do not capture, and that conclusions drawn from their analysis be appropriately qualified.','hard'),
  (cid,80,275,'gap_fill','The _____ (understand → noun) of institutional _____ (change → noun) requires integration of perspectives from political economy, organizational _____ (theory → noun), and the sociology of _____ (organize → noun).','understanding / change / theory / organizations',NULL,'Understanding (gerund-noun), change (noun), organizations (-tion plural from organize).','medium'),
  (cid,80,276,'gap_fill','The _____ (achieve → noun) of effective governance depends on persistent _____ (commit → noun) to both institutional _____ (strengthen → noun) and political will — two elements whose simultaneous _____ (present → noun) is rare but indispensable.','achievement / commitment / strengthening / presence',NULL,'Achievement (-ment), commitment (-ment), strengthening (gerund-noun), presence (-ence from present adj.).','hard'),
  (cid,80,277,'gap_fill','The _____ (recognize → noun) that governance requires ongoing _____ (invest → noun) rather than one-time fixes is foundational to any serious approach to its _____ (improve → noun).','recognition / investment / improvement',NULL,'Recognition (-tion), investment (-ment), improvement (-ment).','medium'),
  (cid,80,278,'gap_fill','The _____ (study → noun) of governance remains one of the most important intellectual enterprises of our time, demanding the best of our analytical _____ (capable → noun) in _____ (service → noun) of the most fundamental practical _____ (challenge → noun).','study / capabilities / service / challenges',NULL,'Capabilities (-ility plural), service (noun unchanged), challenges (plain noun plural).','medium'),
  (cid,80,279,'gap_fill','The _____ (argument → noun) that the _____ (fail → noun) of reform is attributable to poor design misidentifies the obstacle and therefore misses the _____ (opportune → noun) for effective _____ (intervene → noun).','argument / failure / opportunity / intervention',NULL,'Failure (-ure), opportunity (-ity from opportune), intervention (-tion).','medium'),
  (cid,80,280,'gap_fill','The _____ (persist → noun) of power asymmetries in international _____ (relate → noun) necessitates the _____ (develop → noun) of multilateral mechanisms for conflict _____ (resolve → noun).','persistence / relations / development / resolution',NULL,'Persistence (-ence), relations (-tion), development (-ment), resolution (-tion).','hard'),
  (cid,80,281,'production','[TOEFL Writing — 200 words] Write a paragraph on corruption and governance failure using nominalization.','',NULL,'The relationship between corruption and governance failure is among the most extensively studied in comparative politics, yet the characterization of this relationship remains contested. The conventional understanding of corruption as a cause of governance failure — the observation that the diversion of public resources to private benefit undermines the capacity of institutions to perform their mandated functions — has been supplemented by recognition that corruption is also a symptom of deeper institutional weaknesses. The identification of corruption as both cause and consequence of governance failure points to the possibility of self-reinforcing dynamics in which the deterioration of governance quality creates conditions that encourage corrupt behavior, which in turn accelerates further deterioration. The implication for reform is significant: if corruption is embedded in a self-reinforcing system, the achievement of improvement requires simultaneous intervention at multiple points rather than sequential treatment of one dimension at a time. The measurement of corruption, typically through perception-based indicators, introduces additional complexity, since the perception of corruption does not always align precisely with its actual prevalence — a discrepancy with important implications for the interpretation of evidence about the effectiveness of anti-corruption interventions.','hard'),
  (cid,80,282,'gap_fill','The _____ (create → noun) of conditions for successful reform requires not better design but more effective _____ (manage → noun) of the political environment — the _____ (cultivate → noun) of coalitions, the _____ (reduce → noun) of opposition, and the _____ (establish → noun) of feedback mechanisms.','creation / management / cultivation / reduction / establishment',NULL,'Creation (-tion), management (-ment), cultivation (-tion), reduction (-tion), establishment (-ment).','hard'),

  -- BLOCK 81: Produção avançada (9 ex)
  (cid,81,283,'production','[TOEFL Writing — 200 words] Write a paragraph on the conditions for institutional resilience using nominalization.','',NULL,'Institutional resilience — the capacity of an organization to maintain its core functions and values under conditions of environmental pressure — depends on several reinforcing factors whose simultaneous presence is rare but whose combination produces institutions capable of surviving over extended periods. The clarity of mission is fundamental: without shared understanding of the institution''s purpose and the values that guide its operation, the deterioration of performance under pressure is difficult to prevent. The quality of leadership provides a second foundation: the demonstration through consistent behavior over time that the values articulated by leadership are genuine rather than rhetorical creates the kind of organizational culture that sustains performance when external conditions are unfavorable. The adequacy of resources is a third condition: institutions whose capacity to perform their functions depends on resources that are vulnerable to political manipulation are inherently more fragile than those whose resource base is protected from such interference. The existence of feedback mechanisms — processes for the detection of underperformance and the adaptation of strategy in response — provides the fourth foundation of resilience. Institutions that possess all four of these characteristics simultaneously are rare; their rarity explains both the value of comparative analysis aimed at understanding how they develop and the importance of protecting them once they exist.','hard'),
  (cid,81,284,'gap_fill','The _____ (complex → noun) of implementation _____ (challenge → noun) requires both technical _____ (expert → noun) and political _____ (skill → noun) — a _____ (combine → noun) that is rarely available in sufficient _____ (measure → noun) simultaneously.','complexity / challenges / expertise / skill / combination / measure',NULL,'Complexity (-ity), expertise (-ise to -ise or irregular), combination (-tion).','hard'),
  (cid,81,285,'gap_fill','The _____ (failure → noun) to align formal _____ (incentive → noun) with the _____ (goal → noun) of the _____ (organization → noun) is a principal source of the _____ (gap → noun) between formal _____ (mandate → noun) and actual _____ (perform → noun).','failure / incentives / goals / organization / gap / mandate / performance',NULL,'Performance (-ance), failure (-ure), incentives (plain noun plural).','hard'),
  (cid,81,286,'gap_fill','The _____ (observation → noun) that _____ (learn → noun) from _____ (fail → noun) is a precondition for _____ (improve → noun) has important _____ (implication → noun) for the _____ (design → noun) of _____ (organizational → noun) review _____ (process → noun).','observation / learning / failure / improvement / implications / design / organizational / processes',NULL,'Learning (gerund-noun), improvement (-ment), implications (-tion).','hard'),
  (cid,81,287,'gap_fill','The _____ (achieve → noun) of lasting _____ (improve → noun) in governance _____ (perform → noun) requires _____ (attend → noun) to the _____ (quality → noun) of _____ (lead → noun) as well as to formal _____ (structure → noun) and _____ (procedure → noun).','achievement / improvement / performance / attention / quality / leadership / structures / procedures',NULL,'Achievement (-ment), improvement (-ment), performance (-ance), leadership (-ship).','hard'),
  (cid,81,288,'gap_fill','The _____ (relationship → noun) between _____ (formal → noun) _____ (design → noun) and _____ (outcome → noun) is _____ (mediate/passive) by _____ (informal → noun) _____ (norm → noun), _____ (culture → noun), and the _____ (quality → noun) of _____ (implementation → noun).','relationship / formal / design / outcomes / mediated / informal / norms / culture / quality / implementation',NULL,'Mediated (passive), informal norms (plain nouns), implementation (-tion).','medium'),
  (cid,81,289,'gap_fill','The _____ (process → noun) of _____ (institutional → noun) _____ (reform → noun) involves the _____ (navigate → noun) of competing _____ (interest → noun), the _____ (management → noun) of _____ (resist → noun), and the _____ (build → noun) of _____ (coalition → noun) sufficient to sustain change over time.','process / institutional / reform / navigation / interests / management / resistance / building / coalitions',NULL,'Navigation (-tion from navigate), resistance (-ance), building (gerund), coalitions (-tion plural).','hard'),
  (cid,81,290,'production','[TOEFL Writing — 200 words] Write a paragraph on the role of leadership in governance using nominalization.','',NULL,'The role of leadership in determining governance outcomes has received growing recognition in the scholarly literature, though the characterization of its influence remains contested. The most influential treatments of the subject converge on the observation that formal authority — the possession of legal power to direct the operations of an institution — is a necessary but not sufficient condition for effective leadership. The exercise of genuine leadership requires, in addition, the development of organizational culture through the demonstration of consistent commitment to institutional values, the cultivation of trust among those within the organization and those it serves, and the maintenance of the kind of credibility that comes only from sustained alignment between articulated values and observable behavior. The measurement of leadership quality is inherently difficult, since many of its most important dimensions — the quality of judgment in conditions of uncertainty, the capacity to inspire commitment to a shared mission, the ability to navigate political pressures without compromising institutional integrity — are resistant to straightforward operationalization. The implication for governance reform is significant: the transformation of institutional performance depends not only on the redesign of formal structures and incentive systems but on the development of leadership capacity in ways that are more difficult to plan and execute than structural reform but ultimately more consequential for sustained improvement.','hard'),
  (cid,81,291,'gap_fill','The _____ (tension → noun) between the _____ (requirement → noun) for short-term _____ (result → noun) and the _____ (necessity → noun) of long-term _____ (invest → noun) in _____ (institutional → noun) _____ (capacity → noun) is one of the most persistent _____ (dilemma → noun) of governance _____ (reform → noun).','tension / requirement / results / necessity / investment / institutional / capacity / dilemmas / reform',NULL,'Requirement (-ment), necessity (-ity), investment (-ment), dilemmas (plain noun plural).','hard'),

  -- BLOCK 82: Capstone final (9 ex)
  (cid,82,292,'production','[TOEFL Writing — 200 words] Write a conclusion on what the study of governance has established.','',NULL,'The body of research reviewed in this paper has established several propositions about governance reform with a degree of confidence that justifies their incorporation into the foundations of policy practice. The first is that the determinants of governance quality are multiple and interconnected, and that reforms focused on a single dimension are unlikely to produce sustained improvement. The second is that the political economy of reform — the distribution of the costs and benefits of change and the organization of support and opposition — is as important to the determination of reform outcomes as the technical quality of reform design. The third is that the achievement of reform is not the end of the story: the maintenance of improvement requires ongoing investment in organizational cultures, incentive systems, and accountability mechanisms that prevent the natural tendencies toward entropy from reversing the gains achieved. And the fourth is that the measurement of governance quality, imperfect as it is, is essential to the management of reform — both because it provides the evidence base for design and because it creates the visibility of performance that accountability requires. These propositions do not constitute a blueprint, but they represent the most reliable guidance that current knowledge can offer.','hard'),
  (cid,82,293,'gap_fill','The _____ (future → noun) of governance _____ (research → noun) lies in the _____ (integrate → noun) of insights from multiple disciplines and the _____ (develop → noun) of closer _____ (connect → noun) between academic _____ (analysis → noun) and policy practice.','future / research / integration / development / connections / analysis',NULL,'Integration (-tion from integrate), development (-ment), connections (-tion plural).','medium'),
  (cid,82,294,'gap_fill','The _____ (translate → noun) of research findings into policy-relevant advice requires intellectual _____ (humble → noun) about the _____ (limit → noun) of current knowledge and practical _____ (wise → noun) about the conditions under which evidence can be effectively used.','translation / humility / limits / wisdom',NULL,'Translation (-tion), humility (-ity), limits (plain noun), wisdom (-dom from wise).','hard'),
  (cid,82,295,'gap_fill','The _____ (recognition → noun) that _____ (govern → noun) is a dynamic _____ (achieve → noun) rather than a static _____ (condition → noun) — requiring continuous _____ (invest → noun) in _____ (renew → noun) rather than mere _____ (preserve → noun) of what exists — is perhaps the most important insight that governance _____ (scholarship → noun) can offer.','recognition / governance / achievement / condition / investment / renewal / preservation / scholarship',NULL,'Achievement (-ment), investment (-ment), renewal (-al), preservation (-tion from preserve).','hard'),
  (cid,82,296,'gap_fill','The _____ (accumulate → noun) of knowledge about what makes governance work has progressed substantially, but significant gaps in _____ (understand → noun) remain — particularly with respect to the _____ (mechanism → noun) through which formal _____ (institutional → noun) change produces behavioral change.','accumulation / understanding / mechanisms / institutional',NULL,'Accumulation (-tion), understanding (gerund-noun), mechanisms (plain noun), institutional (adjective).','medium'),
  (cid,82,297,'production','[TOEFL Writing — 200 words] Final capstone: Write a synthesis on good governance and what it requires.','',NULL,'The achievement of good governance — a standard aspired to universally but attained rarely and maintained with difficulty — requires the simultaneous fulfillment of conditions that are individually demanding and collectively rare. The development of clear institutional mandates, the creation of effective accountability mechanisms, the cultivation of professional cultures that take those mandates seriously, and the availability of leadership capable of navigating the political environment while protecting institutional integrity are all necessary conditions, none sufficient on its own. The recognition that good governance is a dynamic achievement rather than a static condition — that it requires continuous investment in renewal rather than merely the preservation of what exists — is perhaps the most important insight that the study of governance can offer. The measurement of governance quality, despite its difficulties, is essential to the maintenance of this investment, since without systematic assessment of whether performance is improving or declining, the pressures that drive deterioration are likely to prevail. And the cultivation of a governance culture — in which the quality of public institutions is treated as a shared responsibility rather than a technical matter for specialists — is ultimately the foundation on which all other elements depend. Without that culture, the structures may be built but will not be maintained; with it, even imperfect structures can deliver more than their formal design would suggest possible.','hard'),
  (cid,82,298,'gap_fill','The _____ (invest → noun) in bridging _____ (capability → noun) — the _____ (capacity → noun) to translate analytical _____ (find → noun) into policy-relevant _____ (guidance → noun) — is the most practical _____ (contribution → noun) that academic _____ (study → noun) of governance can make.','investment / capabilities / capacity / findings / guidance / contribution / study',NULL,'Investment (-ment), capabilities (-ility plural), findings (gerund-noun), contribution (-tion).','hard'),
  (cid,82,299,'gap_fill','The _____ (generation → noun) that follows us, whose _____ (welfare → noun) depends in part on the _____ (quality → noun) of the _____ (institution → noun) we leave them, deserves our best _____ (effort → noun) at building those institutions well.','generation / welfare / quality / institutions / effort',NULL,'All plain nouns or derived forms. Welfare (from well + -fare), institutions (-tion).','medium'),
  (cid,82,300,'production','[TOEFL Writing — Final capstone] Write a 200-word conclusion on what future governance scholarship should prioritize using nominalization throughout.','',NULL,'The agenda for future governance scholarship, which must balance the demand for theoretical rigor with the urgency of practical problems, should be organized around several priorities. The most pressing is the development of a more robust understanding of the conditions under which institutional reform succeeds — not just the documentation of cases, which has been extensive, but the identification of mechanisms, whose specification would allow findings to be applied in new contexts. A second priority is the development of better measures of institutional quality that would allow researchers to track change over time with greater precision than current indicators permit. The indicators currently available, which rely heavily on expert perceptions, provide at best a rough approximation of the multidimensional concept they are supposed to capture. A third priority is the integration of insights from multiple disciplines — economics, political science, sociology, and organizational behavior — whose separate literatures have each illuminated different aspects of a problem that is inherently multidisciplinary. The cultivation of research partnerships that bridge the worlds of knowledge production and policy application is perhaps the most immediate practical contribution that the scholarship can make. The investment in these partnerships — difficult to organize, difficult to sustain, but capable of producing knowledge that neither academic research nor policy practice could generate alone — is in the end what meaningful progress on the governance challenge requires.','hard')

